def static_contract(supervisors):
    assets=dict(STATIC['assets'])
    assets.update({'supervisor/'+n:dict(d) for n,d in supervisors.items()})
    return {'kind':'whole-pgd-whole-scratch-v1','assets':assets,
        'runtime_files':STATIC['runtime_files'],'result':STATIC['result'],
        'root_metadata':STATIC['root_metadata'],'caps':STATIC['caps'],'packet':STATIC['packet']}

def validate_policy(p, supervisors):
    if type(p) is not dict or set(p) != {'kind', 'scratch_contract_text', 'base_text', 'design_text', 'scope'} or p['kind'] != 'whole-pgd-runtime-policy-v1':
        raise ValueError('Exact component-only policy required.')
    if p['base_text'] != STATIC['base_text'] or p['design_text'] != STATIC['design_text'] or p['scope'] != STATIC['scope']:
        raise ValueError('Original scientific/host/resource policy changed.')
    if type(supervisors) is not dict or set(supervisors) != set(SUPERVISORS.values()):
        raise ValueError('Nine exact supervisor slots required.')
    for name, d in supervisors.items():
        if type(d) is not dict or set(d) != {'bytes', 'sha256'} or type(d['bytes']) is not int or (not 0 < d['bytes'] <= 2 * 2 ** 20) or (not sha(d['sha256'])):
            raise ValueError('Bounded supervisor descriptor required.')
    if any((supervisors[n]['sha256'] != want for n, want in STATIC['fixed_support'].items())):
        raise ValueError('Frozen proof/owned-monitor bytes changed.')
    expected = static_contract(supervisors)
    if p['scratch_contract_text'] != encoded(expected).decode():
        raise ValueError('Exact whole component scratch catalogue required.')
    return p
